public int maxMin(int k, int[] arr) {
    int n = arr.length;
    int best = Integer.MAX_VALUE;
    int[] combo = new int[k];
    best = combine(arr, k, 0, 0, combo, best);
    return best;
}

private int combine(int[] arr, int k, int start, int depth, int[] combo, int best) {
    if (depth == k) {
        int mn = combo[0], mx = combo[0];
        for (int v : combo) { mn = Math.min(mn, v); mx = Math.max(mx, v); }
        return Math.min(best, mx - mn);
    }
    for (int i = start; i < arr.length; i++) {
        combo[depth] = arr[i];
        best = combine(arr, k, i + 1, depth + 1, combo, best);
    }
    return best;
}

