public int maxMin(int k, int[] arr) {
    Arrays.sort(arr);
    int best = Integer.MAX_VALUE;
    for (int i = 0; i + k - 1 < arr.length; i++) {
        best = Math.min(best, arr[i + k - 1] - arr[i]);
    }
    return best;
}

